package io.github.polestarcn.companion;
import static org.junit.Assert.*;import android.content.*;import android.os.*;import java.lang.reflect.*;import java.util.concurrent.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class EnergyCrashBeta6Test {
 Context c;EnergyLog log;String id="abcdef1234567890";
 @Before public void setup()throws Exception{c=RuntimeEnvironment.getApplication();Field f=EnergyLog.class.getDeclaredField("instance");f.setAccessible(true);EnergyLog prior=(EnergyLog)f.get(null);if(prior!=null)prior.close();f.set(null,null);c.deleteDatabase("energy_history.db");c.getSharedPreferences("preferences",0).edit().clear().commit();log=EnergyLog.get(c);}
 @Test public void firstHistorySampleWithoutClimateSocDoesNotCrashChart()throws Exception{long now=System.currentTimeMillis();VehicleSnapshot s=new VehicleSnapshot("Fixture","masked",85,312,12000,"空闲","全部关闭","全部关闭","已关闭","已上锁",now,"LIVE",false,"关闭","关闭");log.append(id,s);assertNull(log.read(id,1).points.get(0).soc);org.robolectric.android.controller.ActivityController<EnergyActivity> controller=Robolectric.buildActivity(EnergyActivity.class,new Intent(c,EnergyActivity.class).putExtra("vehicle",id)).setup();try{EnergyLog.WORK.submit(()->{}).get(10,TimeUnit.SECONDS);Shadows.shadowOf(Looper.getMainLooper()).idle();assertFalse(controller.get().isFinishing());}finally{controller.pause().stop().destroy();}}
 @Test public void signedInVehicleWithNoLocalHistoryStillOpensEnergyPage()throws Exception{VehicleCoordinator m=VehicleCoordinator.get(c);m.selected=new io.github.polestarcn.companion.api.ChinaPolestarApi.VehicleInfo();m.selected.vin="NO-LOCAL-HISTORY";org.robolectric.android.controller.ActivityController<EnergyActivity> controller=Robolectric.buildActivity(EnergyActivity.class).setup();try{EnergyLog.WORK.submit(()->{}).get(10,TimeUnit.SECONDS);Shadows.shadowOf(Looper.getMainLooper()).idle();assertFalse(controller.get().isFinishing());}finally{controller.pause().stop().destroy();m.selected=null;}}
}
